ValidationRule.errorConditionFormula:
AND( ISCHANGED(Status), NOT(OR(
/* PRE-LOTTERY: → Eligible */ AND(NOT(Has_Lottery_Run__c), OR(TEXT(PRIORVALUE(Status)) = "Submitted", TEXT(PRIORVALUE(Status)) = "Withdrawn/Declined", TEXT(PRIORVALUE(Status)) = "Rescinded"), TEXT(Status) = "Eligible"),
/* PRE-LOTTERY: Submitted → Withdrawn/Declined */ AND(NOT(Has_Lottery_Run__c), TEXT(PRIORVALUE(Status)) = "Submitted", TEXT(Status) = "Withdrawn/Declined"),
/* POST-LOTTERY: → Waitlisted */ AND(Has_Lottery_Run__c, OR(TEXT(PRIORVALUE(Status)) = "Submitted", TEXT(PRIORVALUE(Status)) = "Withdrawn/Declined", TEXT(PRIORVALUE(Status)) = "Rescinded", TEXT(PRIORVALUE(Status)) = "Pre-Offer"), TEXT(Status) = "Waitlisted"),
/* POST-LOTTERY: Waitlisted → Pre-Offer */ AND(Has_Lottery_Run__c, TEXT(PRIORVALUE(Status)) = "Waitlisted", TEXT(Status) = "Pre-Offer"),
/* POST-LOTTERY: Eligible &rarr; Pre-Offer */ AND(Has_Lottery_Run__c, TEXT(PRIORVALUE(Status)) = "Eligible", TEXT(Status) = "Pre-Offer"),
/* POST-LOTTERY: Pre-Offer → Seat Offered */ AND(Has_Lottery_Run__c, TEXT(PRIORVALUE(Status)) = "Pre-Offer", TEXT(Status) = "Seat Offered"),
/* POST-LOTTERY: Pre-Offer → Offer Rescinded due to Seat Optimization */ AND(Has_Lottery_Run__c, TEXT(PRIORVALUE(Status)) = "Pre-Offer", TEXT(Status) = "Offer Rescinded due to Seat Optimization"),
/* POST-LOTTERY: Seat Offered &rarr; Offer Rescinded due to Seat Optimization */ AND(Has_Lottery_Run__c, TEXT(PRIORVALUE(Status)) = "Seat Offered", TEXT(Status) = "Offer Rescinded due to Seat Optimization"),
/* POST-LOTTERY: Seat Offered → Accepted */ AND(Has_Lottery_Run__c, TEXT(PRIORVALUE(Status)) = "Seat Offered", TEXT(Status) = "Accepted"),
/* POST-LOTTERY: → Withdrawn/Declined */ AND(Has_Lottery_Run__c, OR(TEXT(PRIORVALUE(Status)) = "Eligible", TEXT(PRIORVALUE(Status)) = "Waitlisted", TEXT(PRIORVALUE(Status)) = "Seat Offered", TEXT(PRIORVALUE(Status)) = "Seat Accepted"), TEXT(Status) = "Withdrawn/Declined") )) )
